"""Integrate the researched editorial collection without replacing the existing library."""
from pathlib import Path
from bs4 import BeautifulSoup as Soup
import json,re,html,subprocess
R=Path(__file__).resolve().parents[2]
def e(x):return html.escape(str(x),quote=True)
def frag(s):return Soup(s,'html.parser')
books=sum([json.loads(p.read_text()) for p in sorted((R/'.github/data').glob('garden-books-0[1-5].json'))],[])
assert len(books)==100 and sorted(b['rank'] for b in books)==list(range(1,101))
covers=json.loads((R/'.github/data/garden-book-covers.json').read_text());covers={x['rank']:x for x in covers}
for b in books:
 b['slug']=re.sub('[^a-z0-9]+','-',b['title'].lower()).strip('-')+'-'+str(b['rank'])
 assert re.fullmatch('[A-Z0-9]{10}',b['amazonAsin']) and b['amazonUrl']=='https://www.amazon.com/dp/'+b['amazonAsin']
 assert covers[b['rank']]['verified'];b.update({k:v for k,v in covers[b['rank']].items() if k not in ['title','authors','rank']})
books.sort(key=lambda b:b['rank'])
out=R/'books';out.mkdir(exist_ok=True)
(out/'catalog.json').write_text(json.dumps({'title':'100 Notable and Influential Gardening Books','editorial':True,'affiliateEnabled':False,'books':books},ensure_ascii=False,indent=2))
base=Soup((R/'articles/index.html').read_text(),'html.parser')
header=str(base.select_one('.b21StickyBrand'));footer=str(base.footer)
styles=''.join(str(x) for x in base.head.select('link[rel=stylesheet]'))+'<link rel="stylesheet" href="/app-assets/garden-books.css?v=20261021-books">'
scripts=''.join(str(x) for x in base.select('script[src]') if any(v in x.get('src','') for v in ['site-experience','app-navigation','install.js']))+'<script src="/app-assets/garden-books.js?v=20261021-books" defer></script>'
def shell(title,body):return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+' | Perennial Home &amp; Gardens</title>'+styles+'</head><body>'+header+body+footer+scripts+'</body></html>'
shelf='''<section class="phg-books" id="phgBooks"><header><span class="phg-books-kicker">Perennial Garden Library · Books worth growing with</span><h2>100 Notable and Influential Gardening Books</h2><p class="phg-books-intro">A reading companion for the garden you want to grow. Explore practical guides, enduring classics and new ways to understand soil, food, flowers and habitat. Begin with 25 selections, then reveal more at your own pace.</p></header><details class="phg-books-method"><summary>How we chose and ordered the collection</summary><p>This is Perennial’s editorial collection, not a bestseller list or an objective historical ranking. We weigh practical usefulness, influence, distinctive ideas and relevance to home gardeners. Older works are read in their historical context; local extension guidance and current safety advice take priority.</p><p>Jimmy Williams and Susan Heeger’s <em>From Seed to Skillet</em> appears at #12. Jimmy is Wayne’s uncle. We disclose that personal connection and also value the book’s link between family history, growing food and cooking it.</p><p>Each guide identifies a particular edition, gives our original summary and selection rationale, and links to bibliographic sources. Covers come from Open Library or publishers, with credits on each guide.</p></details><div class="phg-book-controls"><label>Search books<input id="phgBookSearch" type="search" placeholder="Title, author or subject"></label><label>Category<select id="phgBookCategory"><option value="">All categories</option></select></label><label>Reading shelf<select id="phgBookShelf"><option value="">All books</option><option value="saved">My reading list</option></select></label><label>Sort<select id="phgBookSort"><option value="rank">Editorial order</option><option value="title">Title A–Z</option><option value="year">Original publication year</option></select></label></div><p id="phgBooksStatus" class="phg-books-status" role="status">Loading the collection…</p><div id="phgBooksGrid" class="phg-books-grid"></div><div class="phg-books-pagination"><button id="phgBooksMore" type="button">See More · 25 more books</button><button class="phg-book-export" type="button" data-book-export>Export my reading notes</button></div><p class="phg-book-link-note">“View on Amazon” opens a retailer listing. Links currently contain no affiliate tracking. Prices, stock and editions may change; check the retailer’s details. Reading lists and notes stay in this browser. Clearing browser data removes them; export a backup to keep them.</p><noscript><p>JavaScript enables filtering and private notes. Browse all 100 book guides below.</p>STATIC_LIST</noscript></section>'''
shelf=shelf.replace('STATIC_LIST','<ol>'+''.join('<li><a href="/books/'+b['slug']+'.html">'+e(b['title'])+'</a> — '+e(' · '.join(b['authors']))+'</li>' for b in books)+'</ol>')
(out/'index.html').write_text(shell('100 Notable and Influential Gardening Books','<main>'+shelf+'</main>'))
for i,b in enumerate(books):
 credit='<a class="phg-book-cover-credit" href="'+e(b['coverSourceUrl'])+'" target="_blank" rel="noopener">'+e(b['coverCredit'])+'</a>'
 family='<p class="phg-book-family-note">A personal connection: Jimmy Williams is Wayne’s uncle. This family relationship is part of our reason for highlighting this book, alongside its celebration of growing, cooking and passing garden knowledge between generations.</p>' if b['rank']==12 else ''
 related=[x for x in books if x['category']==b['category'] and x!=b][:3]
 body='<main class="phg-book-shell" data-book-id="'+b['slug']+'"><a class="phg-book-back" href="/tools/garden-library/#phgBooks">← Back to the Garden Library</a><header class="phg-book-head"><div><img class="phg-book-cover" src="'+e(b['coverUrl'])+'" alt="Cover of '+e(b['title'])+'">'+credit+'</div><div><span class="phg-books-kicker">Perennial’s editorial selection #'+str(b['rank'])+'</span><h1>'+e(b['title'])+'</h1><p class="phg-book-subtitle">'+e(' · '.join(b['authors']))+'</p><p class="phg-book-edition">Selected edition: '+e(b.get('editionYear',b.get('year','See source')))+' · ISBN '+e(b['isbn13'])+'</p><div class="phg-book-meta"><span>'+e(b['category'])+'</span><span>Editorial reading guide</span></div><p>'+e(b['bestFor'])+'</p><div class="phg-book-actions"><a class="phg-app-open phg-book-amazon" href="'+e(b['amazonUrl'])+'" target="_blank" rel="noopener noreferrer">View on Amazon ↗</a><button class="phg-book-save" data-book-save="'+b['slug']+'" type="button"></button></div></div></header>'+family+'<nav class="phg-book-outline" aria-label="Book guide"><a href="#summary">About the book</a><a href="#selection">Why this selection</a><a href="#use">Put it to work</a><a href="#notes">My notes</a><a href="#sources">Sources</a></nav><div class="phg-book-reading-guide"><div>'
 for id,title,key in [('summary','About the book','summary'),('selection','Why we placed it here','whyChosen'),('use','Put this book to work','practicalUse')]:body+='<section id="'+id+'"><h2>'+title+'</h2><p>'+e(b[key])+'</p></section>'
 if b.get('caution'):body+='<p class="phg-book-family-note">Reading context: '+e(b['caution'])+'</p>'
 body+='<section id="notes" class="phg-book-notes"><h2>My reading notes</h2><p>Private to this browser. Save explicitly and export a backup.</p><label for="phgBookReadingStatus">Reading status</label><select id="phgBookReadingStatus"><option value="want">Want to read</option><option value="reading">Reading</option><option value="finished">Finished</option></select><label for="phgBookNotes">Notes and garden ideas</label><textarea id="phgBookNotes" placeholder="What would you try in your garden?"></textarea><button id="phgSaveBookNotes" type="button">Save my notes</button> <button data-book-export type="button">Export notes</button><span id="phgBookNoteStatus" class="phg-book-note-status" role="status"></span></section><section id="sources"><h2>References and edition details</h2><ul class="phg-book-ref"><li><a href="'+e(b['sourceUrl'])+'" target="_blank" rel="noopener">'+e(b['sourceTitle'])+'</a></li><li><a href="'+e(b['coverSourceUrl'])+'" target="_blank" rel="noopener">Cover and catalog record</a></li></ul><p class="phg-book-link-note">Original Perennial commentary; no retailer customer reviews, star ratings or prices are reproduced. The retailer link currently has no affiliate tracking.</p></section></div><aside class="phg-book-aside"><h2>Take the idea outside</h2><a href="/tools/garden-planner/">Map your garden space →</a><a href="/tools/garden-journal/">Record an experiment →</a><a href="/tools/garden-library/">Search plant records →</a><a href="/help/">Help &amp; Tutorials →</a></aside></div><section><h2>Keep exploring</h2><div class="phg-book-related">'+''.join('<a href="/books/'+x['slug']+'.html">#'+str(x['rank'])+' · '+e(x['title'])+'</a>' for x in related)+'</div></section><nav class="phg-book-navigation" aria-label="Previous and next book">'+('<a href="/books/'+books[i-1]['slug']+'.html">← Previous book</a>' if i else '<span></span>')+('<a href="/books/'+books[i+1]['slug']+'.html">Next book →</a>' if i<99 else '')+'</nav></main>'
 (out/(b['slug']+'.html')).write_text(shell(b['title'],body))
p=R/'tools/garden-library/index.html';d=Soup(p.read_text(),'html.parser')
for x in d.select('.phg-library-launches,#phgBooks'):x.decompose()
d.select_one('.hero').insert_after(frag('<nav class="phg-library-launches" aria-label="Garden Library sections"><a class="phg-app-open" href="#phgUnifiedSearch">⌕ Search the Library</a><a class="phg-app-open" href="#phgPlantsPanel" data-library-mode="plants">❧ Plant Records</a><a class="phg-app-open" href="#phgBooks">▥ 100 Gardening Books</a></nav>'))
d.main.append(frag(shelf))
for name,tag,attr in [('garden-books.css','link','href'),('garden-books.js','script','src'),('library-voice.js','script','src')]:
 if not d.select_one(tag+'['+attr+'*="'+name+'"]'):
  n=d.new_tag(tag);n[attr]='/app-assets/'+name+'?v=20261021-books'
  if tag=='link':n['rel']='stylesheet';d.head.append(n)
  else:n['defer']='';d.body.append(n)
for id in ['phgUnifiedMic','mic']:
 button=d.find(id=id);button.clear();button['aria-label']='Start voice search';button['aria-pressed']='false'
 button.append(frag('<svg viewBox="0 0 32 40" aria-hidden="true"><rect x="10" y="2" width="12" height="23" rx="6" fill="currentColor"/><path d="M6 18v3a10 10 0 0 0 20 0v-3M16 31v6M10 37h12" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"/><path d="M13 7h6m-6 5h6m-6 5h6" stroke="#edf2f4" stroke-width="1.6"/></svg>'))
for x in d.select('link[href*="app-navigation.css"]'):x['href']='/app-assets/app-navigation.css?v=20261021-garden-start'
p.write_text(str(d))
# Keep the separately created page and its private notes intact; provide the integrated destination.
p=R/'garden-books.html'
if not p.exists():p.write_bytes(subprocess.check_output(['git','show','origin/main:garden-books.html'],cwd=R))
d=Soup(p.read_text(),'html.parser')
if not d.find(id='phg-integrated-library-link'):
 d.main.insert(0,frag('<aside id="phg-integrated-library-link"><a href="/tools/garden-library/#phgBooks">Explore the expanded Garden Library: matched covers, 100 full book guides and reading notes →</a><p>This original catalog and its saved notes remain available here.</p></aside>'))
p.write_text(str(d));print('Built 100 book guides and integrated the existing Garden Library; preliminary catalog preserved.')
